/* Ticket Booth：中性墨底 + 单一珊瑚强调（避免紫霓虹 AI 默认味） */
:root,
html[data-theme="night"] {
  color-scheme: dark;

  --color-background: oklch(16% 0.012 55);
  --color-background-deep: oklch(12% 0.01 55);
  --color-surface: oklch(20% 0.014 55);
  --color-surface-alt: oklch(24% 0.016 55);
  --color-surface-high: oklch(28% 0.018 55);
  --color-text: oklch(96% 0.01 80);
  --color-muted: oklch(72% 0.02 70);
  --color-line: oklch(38% 0.02 60);
  --color-line-soft: oklch(28% 0.015 55);
  --color-primary: oklch(62% 0.2 28);
  --color-primary-dark: oklch(52% 0.18 28);
  --color-primary-soft: oklch(28% 0.06 30);
  --color-secondary: oklch(68% 0.08 75);
  --color-accent: oklch(82% 0.14 85);
  --color-accent-strong: oklch(74% 0.15 70);
  --color-success: oklch(68% 0.1 150);
  --color-danger: oklch(62% 0.18 28);
  --color-on-primary: oklch(99% 0.01 80);
  --color-ink: var(--color-text);
  --color-highlight: var(--color-accent);

  --shadow-soft: 0 12px 28px oklch(8% 0.01 55 / 45%);
  --shadow-lift: 0 4px 12px oklch(8% 0.01 55 / 35%);
  --header-bg: oklch(14% 0.012 55 / 94%);
  --theme-toggle-track: oklch(22% 0.014 55);
  --celebration-blend: screen;
  --upload-overlay: linear-gradient(oklch(16% 0.012 55 / 42%), oklch(16% 0.012 55 / 48%));

  --body-spot-1: transparent;
  --body-spot-2: transparent;
  --body-spot-3: transparent;
  --body-spot-4: transparent;

  /* Wheel chrome — night: carnival gold on ink, no purple haze */
  --wheel-shell-bg: linear-gradient(145deg, #f0c14b, #d97706 56%, #9a3412);
  --wheel-shell-ring: #fde68a;
  --wheel-shell-outer: #431407;
  --wheel-shell-glow: 0 10px 24px oklch(10% 0.02 50 / 45%);
  --wheel-shell-inner-border: #fef3c7;
  --wheel-shell-inner-shadow: inset 0 0 14px oklch(30% 0.08 50 / 40%);
  --wheel-disc-border: oklch(22% 0.02 55);
  --wheel-disc-inset: inset 0 0 20px oklch(10% 0.01 55 / 50%);
  --wheel-bulb-odd-bg: #fde68a;
  --wheel-bulb-odd-border: #fffbeb;
  --wheel-bulb-odd-glow: 0 0 6px #fcd34d;
  --wheel-bulb-even-bg: #fb7185;
  --wheel-bulb-even-border: #fecdd3;
  --wheel-bulb-even-glow: 0 0 6px #f43f5e;
  --wheel-base-border: oklch(32% 0.02 55);
  --wheel-base-fill: linear-gradient(180deg, oklch(28% 0.02 55), oklch(16% 0.015 55) 70%);
  --wheel-base-mid: linear-gradient(90deg, oklch(18% 0.015 55), oklch(30% 0.02 55) 50%, oklch(18% 0.015 55));
  --wheel-base-mid-border: oklch(34% 0.02 55);
  --wheel-base-bar: linear-gradient(180deg, oklch(26% 0.02 55), oklch(16% 0.015 55) 72%);
  --wheel-base-bar-border: oklch(36% 0.02 55);
  --wheel-base-glow: 0 4px 10px oklch(8% 0.01 55 / 40%);
  --wheel-pointer-bg: linear-gradient(180deg, #ff6b5a, #e11d48);
  --wheel-pointer-border: oklch(78% 0.12 85);
  --wheel-pointer-glow: 0 4px 10px oklch(20% 0.05 30 / 40%);
  --wheel-pointer-top: #ff6b5a;
  --wheel-pointer-mid: #e11d48;
  --wheel-pointer-bottom: #9f1239;
  --wheel-pointer-shine: oklch(92% 0.06 85 / 40%);
  --wheel-pointer-rim-top: #ffe8a3;
  --wheel-pointer-rim-bottom: #d4a017;
  --wheel-pointer-rim-stroke: oklch(72% 0.1 85);
  --wheel-pointer-jewel-light: #ff8fa3;
  --wheel-pointer-jewel: #ff2d55;
  --wheel-spin-border: oklch(82% 0.12 85);
  --wheel-spin-outline: oklch(35% 0.1 30);
  --wheel-spin-bg: oklch(22% 0.02 55);
  --wheel-spin-winner-bg: linear-gradient(145deg, #d97706, #9f1239 75%);
  --wheel-spin-winner-border: #fde68a;
  --wheel-winner-card-bg: oklch(24% 0.03 40);
  --wheel-winner-card-border: oklch(72% 0.12 85);
  --wheel-winner-card-text: oklch(96% 0.02 85);
  --wheel-winner-card-label: oklch(78% 0.1 85);
  --wheel-winner-flash: radial-gradient(circle, oklch(80% 0.12 85 / 28%) 0 14%, transparent 68%);
  --wheel-stage-action-bg: oklch(16% 0.012 55 / 90%);
  --wheel-stage-sticker-bg: oklch(20% 0.014 55 / 90%);
  --wheel-stage-sticker-border: var(--color-line);
  --wheel-stage-sticker-text: var(--color-muted);

  --stage-candy-bg: oklch(15% 0.015 55);
  --stage-candy-image:
    radial-gradient(circle at 22% 14%, oklch(70% 0.1 85 / 40%) 0 1px, transparent 2px),
    radial-gradient(circle at 78% 24%, oklch(62% 0.14 28 / 35%) 0 1px, transparent 2px),
    linear-gradient(145deg, oklch(14% 0.012 55), oklch(17% 0.016 50));
  --stage-sky-bg: oklch(16% 0.02 230);
  --stage-sky-image: radial-gradient(circle at 72% 18%, oklch(55% 0.08 230 / 28%), transparent 34%);
  --stage-sunny-bg: oklch(17% 0.03 75);
  --stage-sunny-image: radial-gradient(circle at 78% 16%, oklch(70% 0.12 85 / 30%), transparent 28%);
  --stage-party-bg: oklch(15% 0.02 40);
  --stage-party-image:
    radial-gradient(oklch(75% 0.12 85) 1px, transparent 1.4px),
    radial-gradient(oklch(65% 0.14 28) 1px, transparent 1.4px);
  --stage-grid-bg: oklch(15% 0.012 55);
  --stage-grid-image:
    linear-gradient(oklch(35% 0.02 55 / 35%) 1px, transparent 1px),
    linear-gradient(90deg, oklch(35% 0.02 55 / 35%) 1px, transparent 1px);
  --stage-notebook-bg: oklch(16% 0.014 55);
  --stage-notebook-image: repeating-linear-gradient(to bottom, transparent 0 25px, oklch(35% 0.02 55 / 30%) 25px 26px);

  --radius: 10px;
  --radius-sm: 7px;
  --font-display: var(--font-display-face), sans-serif;
  --font-body: var(--font-body-face), sans-serif;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
  --header-h: 56px;
}

